 sealed class NewMailboxDialog:Form{readonly TextBox n=new(),s=new();readonly Button create=new(){Text="Create",Enabled=false,AutoSize=true},cancel=new(){Text="Cancel",AutoSize=true};readonly Label err=new(){AutoSize=true,ForeColor=Color.Firebrick};readonly SqliteConnection db;readonly Func<string,string> canon;readonly Func<SqliteConnection,string,string?,bool> nameExists,idExists;bool filtering;public string MailboxName=>n.Text.Trim();public string ServiceName=>s.Text.Trim().ToLowerInvariant();public NewMailboxDialog(SqliteConnection c,Func<string,string> ca,Func<SqliteConnection,string,string?,bool> ne,Func<SqliteConnection,string,string?,bool> ie,Icon icon){db=c;canon=ca;nameExists=ne;idExists=ie;Icon=icon;Text="New mailbox";StartPosition=FormStartPosition.CenterParent;FormBorderStyle=FormBorderStyle.FixedDialog;MinimizeBox=false;MaximizeBox=false;ClientSize=new Size(390,150);var p=new TableLayoutPanel{Dock=DockStyle.Fill,Padding=new Padding(12),ColumnCount=2,RowCount=4};p.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));p.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,100));var ln=new Label{Text="Name",AutoSize=true,Anchor=AnchorStyles.Left};var ls=new Label{Text="Service Name",AutoSize=true,Anchor=AnchorStyles.Left};n.Dock=DockStyle.Fill;s.Dock=DockStyle.Fill;p.Controls.Add(ln,0,0);p.Controls.Add(n,1,0);p.Controls.Add(ls,0,1);p.Controls.Add(s,1,1);p.Controls.Add(err,1,2);var host=new TableLayoutPanel{Dock=DockStyle.Fill,ColumnCount=3,AutoSize=true};host.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));host.ColumnStyles.Add(new ColumnStyle(SizeType.AutoSize));host.ColumnStyles.Add(new ColumnStyle(SizeType.Percent,50));var b=new FlowLayoutPanel{AutoSize=true,WrapContents=false};b.Controls.AddRange([create,cancel]);host.Controls.Add(b,1,0);p.Controls.Add(host,0,3);p.SetColumnSpan(host,2);Controls.Add(p);create.DialogResult=DialogResult.OK;cancel.DialogResult=DialogResult.Cancel;AcceptButton=create;CancelButton=cancel;bool auto=true;n.TextChanged+=(_,_)=>{if(auto)s.Text=canon(n.Text);ValidateNow();};s.TextChanged+=(_,_)=>{if(filtering)return;string filtered=FilterServiceName(s.Text);if(filtered!=s.Text){filtering=true;int pos=Math.Min(s.SelectionStart,filtered.Length);s.Text=filtered;s.SelectionStart=pos;filtering=false;}auto=s.Text==canon(n.Text);ValidateNow();};ValidateNow();}void ValidateNow(){string nn=n.Text.Trim(),ss=s.Text.Trim().ToLowerInvariant();string e=nn.Length==0?"Name is required.":ss.Length==0?"Service Name is required.":nameExists(db,nn,null)?"Name already exists.":idExists(db,ss,null)?"Service Name already exists.":"";err.Text=e;create.Enabled=e.Length==0;}}
